(function () {const header = document.querySelector('.site-header');const navToggle = document.querySelector('.nav-toggle');const nav = document.getElementById('site-nav');function closeMenu() {if (!header || !navToggle) return;header.classList.remove('nav-open');navToggle.setAttribute('aria-expanded', 'false');}if (header && navToggle) {navToggle.addEventListener('click', () => {const expanded = navToggle.getAttribute('aria-expanded') === 'true';navToggle.setAttribute('aria-expanded', String(!expanded));header.classList.toggle('nav-open', !expanded);});document.addEventListener('keydown', (e) => {if (e.key === 'Escape') closeMenu();});document.addEventListener('click', (e) => {if (!header.classList.contains('nav-open')) return;const clickedInside = e.target.closest('.site-header');if (!clickedInside) closeMenu();});nav?.addEventListener('click', (e) => {const link = e.target.closest('a');if (link) closeMenu();});}document.addEventListener('click', (e) => {const a = e.target.closest('a[href^="#"]');if (!a) return;const target = a.getAttribute('href');if (!target || target === '#') return;let node = null;try {node = document.querySelector(target);} catch (err) {return;}if (!node) return;e.preventDefault();node.scrollIntoView({ behavior: 'smooth' });});})();
